def transform(grid):
    out=[row[:] for row in grid]
    # The lower motif is a second instance of the same row patterns. For each
    # corresponding row, extend the pattern with the farther-right endpoint.
    for k in range(min(7, len(grid)-20)):
        top, bot = grid[k], grid[20+k]
        fg=next((v for v in set(top+bot) if v!=9),8)
        rt=max((c for c,v in enumerate(top) if v==fg), default=-1)
        rb=max((c for c,v in enumerate(bot) if v==fg), default=-1)
        if rt>rb:
            for c in range(rb+1,rt+1):
                if top[c]==fg and bot[c]==9: out[20+k][c]=1
        elif rb>rt:
            for c in range(rt+1,rb+1):
                if bot[c]==fg and top[c]==9: out[k][c]=1
    return out

